SELECT * FROM dividend_income_record
WHERE user_id = #{userId} AND account_id = #{accountId}
  AND symbol = #{symbol} AND ex_dividend_date = #{exDividendDate}
LIMIT 1

SELECT COALESCE(SUM(dividend_amount_cny), 0)
FROM dividend_income_record
WHERE user_id = #{userId}
  AND ex_dividend_date BETWEEN #{startDate} AND #{endDate}
